from _lib import File
F=File('pre2020_honda450','o-h45','Honda CRF450R 2010-2019 by generation (2009-2012, 2013-2016, 2017-2020): what changed, dyno and weight, power character, tester settings, maps, known problems and fixes (knowledge push 2026-11)','Honda',['CRF450R','CRF450RX'],list(range(2010,2020)))
R=F.R; M='magazine'; C=['CRF450R']

# ---------------- 2009-2012 generation (first fuel-injected CRF450R)
s=F.src(M,"Motocross Action - 2010 Honda CRF450 race test","https://motocrossactionmag.com/real-tests-2010-mxa-race-test-of-the-honda-crf450","2009")
R('identity','2010 changes',C,[2010],"2010 CRF450R changes on the 2009 fuel-injected platform: a new EFI map, a redesigned automatic decompressor, fork with new seals, more oil and firmer low-speed compression, a shock with a new piston, high-speed adjuster and valving, and the ECU connector moved behind the radiator shroud. Frame geometry is unchanged.",{},'OEM',s)
R('power_feel','2010 dyno and weight',C,[2010],"On a magazine dyno the 2010 CRF450R made 50.90 hp at 8,400 rpm and weighed 226.5 lb, about 10 lb lighter than most of the class. Power is mellow and low-to-mid: best from about 6,000 to 8,200 rpm, flat above 8,000 to the 11,200 rpm limiter.",{'peak_hp':50.9,'peak_rpm':8400,'weight_lb':226.5,'rev_limit_rpm':11200},'MEASURED',s,'high')
R('setups','2010 tester settings',C,[2010],"A magazine test crew's 2010 CRF450R setup: fork 0.48 kg/mm springs (stock 0.46), 355 cc oil, compression 6 clicks out (stock 13), rebound 8 out, legs flush. Shock stock 5.4 kg/mm spring (riders under 175 lb can go one rate softer), 105 mm sag once the fork is stiffened (115 with stock fork springs), high-speed 2 turns out (stock 1-1/2), low-speed 11 clicks out, rebound 15 out (stock 14). Gearing 13/49 in place of 13/48.",{'fork_spring':'0.48 kg/mm (stock 0.46)','fork':'355 cc, comp 6 out, reb 8 out, flush','shock':'5.4 kg/mm, sag 105 mm, HSC 2 turns, LSC 11 out, reb 15 out','gearing':'13/49 (stock 13/48)'},'TUNER',s)
G=[2010,2011,2012]
R('known_issues','2009-2012 weak points and fixes',C,G,"Repeated tester findings on the 2009-2012 CRF450R: it can flame out at low rpm (raise the idle; a flywheel weight of about 17 oz helps), the four-spring clutch slips under hard use (remove the judder spring and narrow plate and fit a full-size plate, add stiffer springs, or fit a six-spring aftermarket clutch), the brakes fade with the disc guards on in long motos, the stock 1.1 radiator cap boils over (1.6-2.0 caps were used) and the engine oil has to be checked on a dipstick.",{'radiator_cap':'1.6, 1.8 or 2.0 in place of 1.1','flywheel_weight_oz':17},'TUNER',s)
R('chassis','2009-2012 handling and the usual fixes',C,G,"The 2009-2012 CRF450R sits low at the front and high at the rear. It oversteers and tucks on turn-in, dives under braking and pushes mid-corner. The cures testers settled on were stiffer fork springs, a longer shock link (lowers the rear about 10 mm) and keeping the steering damper. 2010 measured 96.7 dB, over the 94 dB limit of the time.",{'sound_db_2010':96.7},'TUNER',s)
s=F.src(M,"Motocross Action - 2011 Honda CRF450 test","https://motocrossactionmag.com/2011-honda-crf450-motocross-test-the-bike-that-all-other-bikes-are-measured-by-at-least-when-it-comes-to-sales","2010")
R('identity','2011 changes',C,[2011],"2011 CRF450R changes: throttle body reduced from 50 mm to 46 mm, a muffler 100 mm longer with a 26 mm core (was 36 mm), a remapped EFI, a judder spring and stiffer springs in the clutch, a new shock linkage, lighter fork cartridge parts and a steering damper body enlarged from 20 mm to 24 mm.",{'throttle_body_mm':46,'muffler_core_mm':26},'OEM',s)
R('power_feel','2011 dyno',C,[2011],"The 2011 CRF450R made about 52 hp on a magazine dyno, 1.1 hp more than the 2010. Its best power is from 5,000 to 7,700 rpm and it is flat from there to 11,300 rpm, with a soft hit.",{'peak_hp':'about 52'},'MEASURED',s)
R('setups','2011 tester settings',C,[2011],"A magazine test crew's 2011 CRF450R setup: fork 0.49 kg/mm springs (stock 0.46), 355 cc oil, compression 12 clicks out (stock 13), rebound 8 out, legs flush. Shock 5.4 kg/mm spring, 105 mm sag (110-115 if the stock fork springs stay), high-speed 2 turns out (stock 1-1/2), low-speed 14 clicks out, rebound 14 out. Gearing 13/49 in place of 13/48.",{'fork_spring':'0.49 kg/mm (stock 0.46)','fork':'comp 12 out, reb 8 out, flush','shock':'sag 105 mm, HSC 2 turns, LSC 14 out, reb 14 out','gearing':'13/49 (stock 13/48)'},'TUNER',s)
s=F.src(M,"Motocross Action - 2012 Honda CRF450 test","https://motocrossactionmag.com/mxas-2012-honda-crf450-motocross-test-they-hired-new-test-riders-for-2012","2011")
R('identity','2012 changes',C,[2012],"2012 CRF450R changes: fork springs up to 0.49 kg/mm from 0.46 with 10 cc more oil and stronger lower legs, a new linkage with a softer rate that lowers the rear 5 mm, wider and longer footpegs and Dunlop MX51 tyres. Engine, mapping and exhaust are unchanged. List price was $8,440.",{'fork_spring':'0.49 kg/mm','msrp_usd':8440},'OEM',s)
R('power_feel','2012 dyno and weight',C,[2012],"On a magazine dyno the 2012 CRF450R made 52.59 hp, the lowest of the five Japanese and Austrian 450s that year, and weighed 231 lb without fuel, 7-13 lb less than its rivals. Tractable and easy to ride, flat above about 8,600 rpm. An aftermarket exhaust added about 2.5 hp at peak in testing.",{'peak_hp':52.59,'weight_lb':231},'MEASURED',s,'high')
R('setups','2012 tester settings',C,[2012],"A magazine test crew's 2012 CRF450R setup: fork stock 0.49 kg/mm springs, 365 cc oil, compression 12 clicks out, rebound 9 out, legs flush. Shock 5.4 kg/mm spring, 105 mm sag, high-speed 1 turn out (stock 1-1/2), low-speed 12 clicks out, rebound 13 out. Gearing: 13/49 for novices and vets, 14/52 for faster riders.",{'fork':'365 cc, comp 12 out, reb 9 out, flush','shock':'sag 105 mm, HSC 1 turn, LSC 12 out, reb 13 out','gearing':'13/49 or 14/52'},'TUNER',s)

# ---------------- 2013-2016 generation (twin mufflers, air fork)
s=F.src(M,"Motocross Action - 2013 Honda CRF450 test","https://motocrossactionmag.com/ten-years-ago-today-complete-test-of-the-2013-honda-crf450","2012")
G=[2013,2014,2015,2016]
R('identity','2013 redesign',C,G,"The 2013 CRF450R was a new bike: a frame with main spars 40 mm lower, a shock 14.5 mm shorter mounted lower, twin short mufflers, Kayaba PSF air fork in place of coil springs, exhaust valves up from 30 to 31 mm, compression up from 12.0:1 to 12.5:1, more cam overlap, a stronger gearbox with the same ratios and the return of the six-spring, eight-plate clutch. This platform ran 2013-2016.",{'fork':'Kayaba PSF (air)','compression':'12.5:1','exhaust_valve_mm':31,'clutch':'six springs, eight plates'},'OEM',s)
R('power_feel','2013 dyno and weight',C,[2013],"On a magazine dyno the 2013 CRF450R made 51.55 hp (2012: 52.59) and weighed 234 lb (2012: 231). It is stronger off the bottom than the old engine but gives up its advantage around 7,000 rpm and is flat past about 8,200-9,000 rpm. It measured 116.1 dB on the two-metre test.",{'peak_hp':51.55,'weight_lb':234,'sound_2m_db':116.1},'MEASURED',s,'high')
R('setups','2013-2014 tester settings',C,[2013,2014],"A magazine test crew's 2013-2014 CRF450R setup: fork air pressure 35 psi (Honda recommended 33 psi for 2013, 35 for 2014), compression 11 clicks out (stock 13), rebound 10 out, legs 5 mm up. Shock 5.7 kg/mm spring (stock 5.5), 100 mm sag, high-speed 2 turns out (stock 1-5/8), low-speed 12 clicks out (stock 14), rebound 8 out. Fork pressure climbs by up to 5 psi during a moto, so bleed or reset between motos.",{'fork_psi':35,'fork':'comp 11 out (stock 13), reb 10 out, 5 mm up','shock':'5.7 kg/mm (stock 5.5), sag 100 mm, HSC 2 turns, LSC 12 out, reb 8 out'},'TUNER',s)
R('known_issues','2013 wheel and sprocket spacing',C,G,"On the 2013-2016 CRF450R the countershaft sprocket sits 3 mm further out and the rear hub flange is 3 mm thicker to match. A rear wheel built for the earlier bike, or an aftermarket wheel made to the old spacing, can run the chain out of line and throw it.",{'offset_mm':3},'TUNER',s)
s=F.src(M,"Motocross Action - 2014 Honda CRF450 test","https://motocrossactionmag.com/mxas-2014-honda-crf450-motocross-test-sherlock-holmes-needs-to-look-into-the-case-of-the-missing-horsepower","2013")
R('identity','2014 changes',C,[2014],"2014 CRF450R changes: a narrower intake tract, a longer exhaust port divider, a re-aimed injector with split (dual-timing) injection, muffler cores enlarged from 18.5 to 22 mm, a black valve cover, and fork changes (new valving, one-piece rebound piston, oil quantity 242 cc, recommended pressure 35 psi).",{'fork_psi_recommended':35,'fork_oil_cc':242},'OEM',s)
R('power_feel','2014 dyno and weight',C,[2014],"On a magazine dyno the 2014 CRF450R peaked at 51.97 hp and made 49.57 hp at 9,900 rpm, where the 2014 YZ450F made 58.22. It weighed 236 lb. Strong roll-on power up to about 8,500 rpm, then flat.",{'peak_hp':51.97,'hp_at_9900':49.57,'weight_lb':236},'MEASURED',s,'high')
R('setups','2013-2016 gearing',C,G,"Stock gearing on the 2013-2016 CRF450R is 13/48 and testers found it tall for the low-to-mid power. They went to 13/49, or 14/52 for a ratio in between.",{'stock':'13/48 (3.69)','options':'13/49 (3.77), 14/52 (3.71)'},'TUNER',s)
R('known_issues','2013-2016 weak points and fixes',C,G,"Repeated tester findings on the 2013-2016 CRF450R: a spongy clutch that engages close to the grip (replace the judder spring and narrow plate with a full-size plate and add stiffer springs), flame-outs under hard braking (raise the idle a couple of clicks), air-fork seal wear (low-friction seals and fork skins), fork air valves that are hard to reach, a front brake weaker than the class best (oversize disc; remove the disc guard for long motos), and a shock that kicks in braking bumps (stiffer spring and a longer link, which lowers the rear about half an inch). One 2014 test bike had a throttle position sensor fail.",{},'TUNER',s)
s=F.src(M,"Motocross Action - 2015 Honda CRF450 test","https://motocrossactionmag.com/2015-test-ride-honda-crf450","2014")
R('identity','2015 changes',C,[2015],"2015 CRF450R changes: a revised head, a heat-treated piston, more flywheel inertia, a stronger gearbox, three engine maps on a handlebar button, a shorter exhaust with larger tubes, Kayaba PSF-2 fork (compression in one leg, rebound in the other, high- and low-speed adjusters on the caps), all shock adjusters on the reservoir, a 260 mm front disc and Dunlop MX52 tyres.",{'fork':'Kayaba PSF-2','front_disc_mm':260,'maps':3},'OEM',s)
R('power_feel','2015-2016 dyno',C,[2015,2016],"On a magazine dyno the 2015 and 2016 CRF450R both peaked at 53.03 hp at 8,500 rpm. Soft right off idle, a broad middle, and flat after about 8,500-8,600 rpm. The 2016 weighed 233 lb.",{'peak_hp':53.03,'peak_rpm':8500,'weight_lb_2016':233},'MEASURED',s,'high')
R('ecu_electronics','2015-2016 map button',C,[2015,2016],"The 2015-2016 CRF450R has three maps on a handlebar button: hold it with the engine at low rpm and count the flashes, one for stock, two for mellow, three for aggressive. On the dyno the stock map made 1-2 hp more than the other two everywhere, and testers left it there; the aggressive map is jumpy at first throttle.",{'1_flash':'stock','2_flashes':'mellow','3_flashes':'aggressive'},'MEASURED',s)
R('setups','2015 tester settings (PSF-2)',C,[2015],"A magazine test crew's 2015 CRF450R setup: fork 35 psi, oil height 92 mm, high-speed compression 14 out (stock 11), low-speed compression 12 out, high-speed rebound 10 out, low-speed rebound 10 out (stock 9), legs 5 mm up. Shock 5.7 kg/mm spring (stock 5.5), 100 mm sag, high-speed compression 19 out, low-speed 15 out, rebound 4 out. Rear sprocket 49 in place of 48. Steering damper turned fully in.",{'fork_psi':35,'fork':'HSC 14 out, LSC 12 out, HSR 10 out, LSR 10 out, 5 mm up','shock':'5.7 kg/mm, sag 100 mm, HSC 19 out, LSC 15 out, reb 4 out','gearing':'13/49'},'TUNER',s)
s=F.src(M,"Motocross Action - 2016 Honda CRF450 race test","https://motocrossactionmag.com/2016-honda-crf450","2015")
R('identity','2016 changes',C,[2016],"2016 CRF450R changes: fork 5 mm longer for a slacker head angle, a new rising-rate linkage, a chain roller reduced to 34 mm, adjusters changed from 4 to 8 clicks per turn (so click counts are not comparable with 2015), slightly firmer low-speed compression at both ends and a footpeg bracket with a mud scraper that also fits 2013-2015. No engine changes.",{'clicks_per_turn':8},'OEM',s)
R('setups','2016 tester settings (PSF-2, 8 clicks per turn)',C,[2016],"A magazine test crew's 2016 CRF450R setup: fork 35 psi, oil height 87 mm, high-speed compression 24 out (stock 20), low-speed compression 24 out (stock 22), high-speed rebound 25 out (stock 27), low-speed rebound 27 out, legs flush. Shock 56 N/mm spring (stock 54), 105 mm sag, high-speed compression 21 out (stock 19), low-speed 22 out (stock 20), rebound 21 out (stock 22). Use fork high-speed compression for big-hit bottoming and low-speed for everything else.",{'fork_psi':35,'fork':'HSC 24 out, LSC 24 out, HSR 25 out, LSR 27 out, flush','shock':'56 N/mm (stock 54), sag 105 mm, HSC 21 out, LSC 22 out, reb 21 out'},'TUNER',s)

# ---------------- 2017-2020 generation
s=F.src(M,"Motocross Action - 2017 Honda CRF450 race test","https://motocrossactionmag.com/mxa-race-test-2017-honda-crf450","2016")
G=[2017,2018,2019]
R('identity','2017 redesign',C,G,"The 2017 CRF450R was all new: a finger-follower Unicam head with intake valves 2 mm larger, Showa 49 mm coil-spring fork in place of the air fork, the steering damper dropped, the shock centred and mounted 39 mm lower, shared engine and gearbox oil, a seven-plate clutch, a titanium fuel tank, and new geometry (27.22 degree head angle, 22 mm offset, 4.6 in trail, wheelbase 7 mm shorter). Electric start was an option in 2017. This platform ran 2017-2020.",{'head_angle_deg':27.22,'offset_mm':22,'trail_in':4.6,'fork':'Showa 49 mm coil spring','weight_lb_2017':233},'OEM',s)
R('setups','2017 tester settings',C,[2017],"A magazine test crew's 2017 CRF450R setup: fork springs one step stiffer than stock (0.50 against 0.48 kg/mm), compression 10 clicks out (stock 11), rebound 13 out, legs raised to the second line (stock first). Shock 56 N/mm spring (stock 54), 108 mm sag, high-speed compression 3-1/2 turns out, low-speed 12 clicks out, rebound 7 out (stock 10). Rear sprocket 50 in place of 49.",{'fork_spring':'0.50 kg/mm (stock 0.48)','fork':'comp 10 out, reb 13 out, second line','shock':'56 N/mm (stock 54), sag 108 mm, HSC 3-1/2 turns, LSC 12 out, reb 7 out','gearing':'13/50 (stock 13/49)'},'TUNER',s)
R('ecu_electronics','2017-2018 map button',C,[2017,2018],"The 2017-2018 CRF450R has three maps on the handlebar button: one blue flash stock, two mellow, three aggressive. The stock map sits between the other two and testers raced it. There is no launch control before 2019.",{'1_flash':'stock','2_flashes':'mellow','3_flashes':'aggressive'},'TUNER',s)
R('power_feel','2017 character and sound',C,[2017],"The 2017 CRF450R has a jerky, weak change from low to mid, a strong midrange that hooks up, and more top end than the 2016. It weighed 233 lb, the same as the 2016, and measured 119.7 dB on the two-metre test.",{'weight_lb':233,'sound_2m_db':119.7},'MEASURED',s)
s=F.src(M,"Motocross Action - 2018 Honda CRF450 race test","https://motocrossactionmag.com/mxa-race-test-2018-honda-crf450","2017")
R('identity','2018 changes',C,[2018],"2018 CRF450R changes: electric start standard with a lithium battery (weight up from 233 to 240 lb), stiffer stock springs (fork 0.48 to 0.50 kg/mm, shock 54 to 56 N/mm), revised maps and thinner, more flexible engine hangers. List price rose $300.",{'weight_lb':240,'fork_spring':'0.50 kg/mm','shock_spring':'56 N/mm'},'OEM',s)
R('setups','2018 tester settings',C,[2018],"A magazine test crew's 2018 CRF450R setup: fork stock springs, compression and rebound 12 clicks out (pros 10 and 13, vets and novices 13 and 13), legs raised to the second line; 10 cc more oil is the cheap fix for harshness near the bottom of the stroke. Shock stock 56 N/mm spring (light riders 54), 107 mm sag, high-speed compression 3-1/2 to 3-3/4 turns out, low-speed 10 clicks out, rebound 7 out. A shock link 1.5 mm longer than stock was the testers' pick.",{'fork':'comp 12 out, reb 12 out, second line','shock':'sag 107 mm, HSC 3-1/2 to 3-3/4 turns, LSC 10 out, reb 7 out','link':'1.5 mm longer than stock'},'TUNER',s)
R('known_issues','2017-2019 weak points and fixes',C,G,"Repeated tester findings on the 2017-2019 CRF450R: the clutch judder spring and plate break and the clutch fades (remove the judder parts and add a full friction plate; add stiffer springs sparingly), the radiator fins dent within about 20 hours and the bike boils over when raced hard (radiator sleeves; a 1.6-2.0 cap in place of the stock 1.1), the front brake is weak at a light pull and grabby when squeezed (better fluid, remove the disc guards), the fork is harsh and dives, and the bike shakes its head on fast rough straights (more sag, around 107-108 mm; some riders refit a steering damper). The airbox side vents let in dirt and water.",{'radiator_cap':'1.6 to 2.0 in place of 1.1','sag_mm':'107-108'},'TUNER',s)
R('chassis','2017-2019 handling',C,G,"The 2017-2019 CRF450R turns in sharply but is loose mid-corner and at speed, and it is sensitive to front-to-rear balance: small changes in sag or fork height change it a lot. Testers removed the two rear tank bolts and two exhaust-to-subframe bolts to let the frame flex more.",{},'TUNER',s)
s=F.src(M,"Motocross Action - 2019 Honda CRF450 race test","https://motocrossactionmag.com/mxa-race-test-2019-honda-crf450","2018")
R('identity','2019 changes',C,[2019],"2019 CRF450R changes: a reworked exhaust port, a new clutch lifter and pressure plate, twin scavenge pumps, a five-jet piston oil spray, the kickstarter boss removed from the cases, larger mid-pipes, maps by gear using the shift sensor, launch control with three rev settings, revised fork shims, a lighter, more flexible swingarm with a revised linkage, bars mounted 15 mm lower and a larger front caliper piston (30 mm plus 27 mm).",{'launch_control':'three settings','bars':'15 mm lower'},'OEM',s)
R('power_feel','2019 dyno and weight',C,[2019],"On a magazine dyno the 2019 CRF450R peaked at 60.21 hp, the most in the 2019 class (YZ450F 57.51, 450 SX-F 57.14, FC 450 56.40, KX450 55.86, RM-Z450 54.39). It matched the 2018 below 9,000 rpm and gained 2.25 hp at 10,000, 3.0 at 11,000 and 3.4 at 11,600 rpm. It weighed 238 lb and measured 117.5 dB on the two-metre test.",{'peak_hp':60.21,'weight_lb':238,'sound_2m_db':117.5},'MEASURED',s,'high')
R('setups','2019 tester settings',C,[2019],"A magazine test crew's 2019 CRF450R setup: fork stock 0.50 kg/mm springs, compression 12 clicks out (pros 8, vets 13), rebound 12 out, legs at the stock height. Shock 56 N/mm spring, 108 mm sag (106-110 tried), high-speed compression 3-1/2 turns out, low-speed 10 clicks out, rebound 7 out. The stock map was preferred; the aggressive map felt crisper but made about 1 hp less everywhere.",{'fork':'comp 12 out (pro 8, vet 13), reb 12 out','shock':'sag 108 mm, HSC 3-1/2 turns, LSC 10 out, reb 7 out'},'TUNER',s)

if __name__=='__main__': F.write()
